INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1422761-fin320', 'stk-almax', 'FIN 320', 'info', '{"desc": "سلام عليكم جميعاً\n\nانا اخذت الكورس في سمستر ظ،ظ£ظ، عند استاذ يزيد النفجان\n\nجودة المقرر بشكل عام\n\nالمادة هذي من اهم المواد الرئيسية في التخصص و الي كثر من المواد تبني عليها. المادة طبعاً عامة بشكل كبير و تمر على اللمواضيع بشكل سطحي فا هذا الشي يتطلب منك دووور كبير عشان نكون ملم بالمادة.\n\nالمواضيع التي يغطيها المقرر\nالمادة تغطي المواضيع الاساسية في الاستثمار :\nالاستثمار قصير المدى و ادواته\nالاستثمار طويل المدى و ادواته\nWACC بشكل مفصل\nOptions and Future contracts\nHedging\nCAPM model\n\nالمادة جدا مهمه لطلاب الفايننس و احذر كل الحذر انك تاخذها مع دكتور مشي امورك مثل طلعت التركي او فضلول عشان قريد\n\nاي استفسار حاضرين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fin-320-investments/121022/4", "user": "almax", "ts": 1437287332000, "tid": 121022, "pn": 4}}', 1437287332000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437691-fin320', 'stk-practice', 'FIN 320', 'info', '{"desc": "اخذتها مع طلعت\n\nدخلت الكورس وطلعت ما استفدت الا شي بسيط جدا بالنسبة لكورس يعتبر اهم كورس بالتخصص ، الموضوع الوحيد اللي فهمته Holding period\n\nلا تاخذها مع طلعت اذا ودك تفهم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fin-320-investments/121022/6", "user": "Practice", "ts": 1451686940000, "tid": 121022, "pn": 6}}', 1451686940000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bld-24-fin320', 'stk-bld-24', 'FIN 320', 'doc', '{"docs": [{"id": "stk-dr-f115367", "n": "Dr. Fazlul Miah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت مع الدكتور fin 320 في الترم الي راح 121\n\nاولا الدكتور هذا مب تخصصه, هو تخصصه ايكون لكن الديبارتمنت غاصبته على الكورس هذا والكورس صعب مره. الشرح الصراحه سيء جدا يعني خلص السمستر ولا فهمت شي منه.\n\nالكويزات والمياجر تكون من عنده لكن تكون قريبه من اسئلة التي بي, يعطي هوموركات صعبه شوي.\nبالنسبة للتحضير يحظر آخر الكلاص والى اخر الترم الشباب يجون قبل التحظير بربع ساعه ويوقعون مع انه كل كلاص يقول لا تجون متأخرين عشان التحظير بس.\n\nلكن الذيب ما قصر في النهاية دفني قريد كامل انا مستحق +C وعطان B\n\nالقريد النهائي:+D", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1167513-fin320", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-fazlul-miah/115367/14", "user": "Bld-24", "ts": 1358840447000, "tid": 115367, "pn": 14}}]}', 1358840447000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_kid-fin320', 'stk-the_kid', 'FIN 320', 'doc', '{"docs": [{"id": "stk-dr-f115367", "n": "Dr. Fazlul Miah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا اخذت عنده في سمستر 122 مادة Fin320\n\nالتحضير : ما حولك احد تقدر تخلي اي طالب يحظرك طول السمستر ولا درى عنك\nالتأخير اذا زاد عن حده يتكلم عن اللي يتأخر لكن مايسوي شي لهم\n\nطريقة الشرح : الشرح بالنسبة الى المواضيع المتعلقة بالايكون افهم عليه كل شي يقول\nلكن اذا جيت الى مسائل لها علاقه بالفايننس والانفسمنت ماراح تفهم معاه ولا شي شرح صفرررر\n\nالكويزات : عنده كوزات بعد كل شابتر\nطريقه الكوزات كانت بعض الاحيان تجي نصها تي بي وبعض الاحياء ولا شي تي بي اكثر شي كانت تجي من السلايدات ويركز على الرسومات\nالمياجر: كان في سمسترنا ميجرين\nالميجر الاول كان صعب نصه او اقل كان تي بي\nالميجر الثاني سهل جدا وقليل اسئله التي بي\n\nالفاينلات : الفاينل كان صعب وفيه لف ودوران وقليله اسئله التي بي\nالقريد النهائي: C\nالصوت: مائل الى المتوسط (يجيب النوووووووووووووووووووووم)\nإضافات : عنده هوموركات على الاكسل بعد كل شابتر\nالدكتور طيب و اخلاق و يعطيك حقك لا اقل ولا اكثر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1254754-fin320", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-fazlul-miah/115367/16", "user": "the_kid", "ts": 1377180306000, "tid": 115367, "pn": 16}}]}', 1377180306000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kbsc-fin320', 'stk-kbsc', 'FIN 320', 'doc', '{"docs": [{"id": "stk-dr-f180804", "n": "Dr. Li Lu", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : *\n\nLi lu\n\nالمادة: *\n\nFIN320\n\nطريقة الشرح : *\n\nسيئة جدا ، يفتح السلايدات ويقرا منها وهو جالس بدون شرح او حل امثلة وتمارين\n\nالكويزات :\n\nلا يوجد\n\nالمياجر/ميد:\n\nثابتة من سنتين عبارة اسئلة فهمية وكم سؤال حسابات ما تدري من فين جايبه او كيف ينحل ، و\n\nالفاينل :\n\nالدكتور خسارة تاخذ معاه كورس مهم زي الانفستمنت ، تخرج من المادة مو فاهم فيها ولا شي\n\nطريقة التحضير :\n\nورقة تعدي\n\nالقريد النهائي الخاص بك :\n\nD\nاضافات:", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1507366-fin320", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/li-lu/180804/2", "user": "KBSC", "ts": 1552817646000, "tid": 180804, "pn": 2}}]}', 1552817646000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-fin320', 'stk-guest', 'FIN 320', 'doc', '{"docs": [{"id": "stk-dr-f180804", "n": "Dr. Li Lu", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الترم: 201 ONLINE\nاسم الدكتور : *\n\nLi lu\n\nالمادة: FIN320\n\nطريقة الشرح :\n\nيفتح السلايدات ويقرا منها ويحل تمارين الهومورك\nالوضع معاه self study وإذا عندك أي استفسار يكون موجود في الساعات المكتبية على زووم\n\nالكويزات : TB\nاعطانا كويزين وكل كويز 10% !!!!\n\nالمياجر/ميد: TB\nالفاينل :TB\n\nوالوضع غش في كل الاختبارات والكويزات لأن الاسئلة موجودة في النت والتي بي\nالدكتور خسارة تاخذ معاه كورس مهم زي الانفستمنت ، تخرج من المادة مو فاهم فيها ولا شي\n\nطريقة التحضير : ما حضر إلا 3 مرات طول السمستر لكن لو غبت مره يخصم لك أكثر من 1%\n\nالقريد النهائي الخاص بك : D+\n\nالهوموركات: كل شابتر يعطي هورموك وغالباً يكون متوسط إلى طويل\n\nالبروجكت: صعب نسبياً وأعلى مجموعة أخذت 15.5من 20\n\nاضافات:\nرأيي الشخصي، إذا تبغا تفهم المادة معاه، فالوضع بيكون 90% self study وتركز في الكلاسات وتكلمه في الأوفس أور\nإذا تبغا قريد بس،فكل اسئلته TB ونص الشعب جايب فل في الكويزات والميد والفاينل بالغش من قوقل والتي بي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527799-fin320", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/li-lu/180804/5", "user": "Guest", "ts": 1610347009000, "tid": 180804, "pn": 5}}]}', 1610347009000, 1794768220, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
